export const SAVE='astro-kitty-earth-center-v2';
export const LABS=[
{id:'float',name:'Float Lab',short:'Balance. Float. Repair.',icon:'≈',room:'POOL 01',why:'We practise underwater so Kitty can learn to work while floating. Balance the forces, then fix the antenna.',fact:'Astronauts practise spacewalk tasks in a large pool. Buoyancy supports them, but gravity still acts and water creates drag.',model:'Pack strengths are game units. Kitty’s suit and support team keep this virtual pool drill safe.',url:'https://www.nasa.gov/johnson/neutral-buoyancy-laboratory/'},
{id:'rover',name:'Rover Test Yard',short:'Draw a safe route.',icon:'⌁',room:'YARD 02',why:'Plan a route around the rocks. Visit both sample flags, then reach the habitat. A rover needs a plan before it moves.',fact:'Mars rover teams plan routes and send commands in advance because radio messages take minutes to travel between Earth and Mars.',model:'This is an Earth test yard. Route points and driving speed are simplified; many safe routes can work.',url:'https://www.jpl.nasa.gov/edu/resources/lesson-plan/explore-mars-with-scratch/'},
{id:'garden',name:'Grow Lunch',short:'Three plants need you.',icon:'❀',room:'BIO LAB 03',why:'Our crew needs fresh food. Read each plant’s sensor, then share the supplies: two water portions, one lamp and one nutrient dose.',fact:'Space plants need water, light, nutrients and air at their roots. Too much water can reduce root aeration. Sensors help identify what a plant needs.',model:'Needs are known from the pictured sensors. Recovery is sped up; leaf appearance alone does not diagnose every real plant.',url:'https://www.nasa.gov/exploration-research-and-technology/growing-plants-in-space/'},
{id:'gravity',name:'Gravity Playground',short:'Pick two. Predict. Drop.',icon:'↓',room:'PHYSICS 04',why:'Choose two objects and predict how they fall. Compare Earth and Mars, or switch off air in the test chamber to investigate gravity.',fact:'Without air resistance, objects released together at the same height fall with the same acceleration regardless of their mass. Mars has weaker surface gravity than Earth.',model:'The drop is 4 metres. Air resistance is an illustrative drag model, not measured object data. The vacuum switch controls the virtual test chamber.',url:'https://nssdc.gsfc.nasa.gov/planetary/lunar/apollo_15_feather_drop.html'},
{id:'chemistry',name:'Air Makers',short:'Turn water into oxygen.',icon:'⚗',room:'LIFE SUPPORT 05',why:'A space crew needs oxygen. Feed water and electricity into the machine, predict the products, then route each gas to the right tank.',fact:'The space station’s oxygen generation system uses electricity to split water into oxygen and hydrogen. Oxygen supplies the cabin; hydrogen is handled separately.',model:'Sealed virtual cartridges represent molecules. This is an animated ECLSS model, not a home chemistry experiment. Other ECLSS systems remove carbon dioxide and recycle water.',url:'https://www.nasa.gov/reference/environmental-control-and-life-support-systems-eclss/'}];
export const NODES=[{x:100,y:390},{x:245,y:330},{x:415,y:375},{x:380,y:215,flag:true},{x:575,y:155},{x:675,y:345},{x:790,y:230,flag:true},{x:940,y:120}];
export const OBSTACLES=[{x:415,y:375,r:42},{x:675,y:345,r:43},{x:540,y:285,r:38},{x:250,y:155,r:36}];
export function routeResult(ids){if(ids[0]!==0||ids.some(i=>!NODES[i]))return{ok:false,why:'Start at point 1.',segments:[]};let segments=[];for(let i=1;i<ids.length;i++){const a=NODES[ids[i-1]],b=NODES[ids[i]],len=Math.hypot(b.x-a.x,b.y-a.y);let hit=1;for(const o of OBSTACLES){const dx=b.x-a.x,dy=b.y-a.y,px=a.x-o.x,py=a.y-o.y,A=dx*dx+dy*dy,B=2*(px*dx+py*dy),C=px*px+py*py-(o.r+14)**2,D=B*B-4*A*C;if(A&&D>=0){const t=(-B-Math.sqrt(D))/(2*A);if(t>=0&&t< hit)hit=t;}}segments.push({a,b,len,hit});if(hit<1)return{ok:false,why:'A rock blocks this route. Try another dot.',segments};}const ok=ids.at(-1)===7&&ids.includes(3)&&ids.includes(6);return{ok,why:ids.at(-1)!==7?'Finish at the habitat: point 8.':'Visit both sample flags: points 4 and 7.',segments};}
export const OBJECTS=[{id:'hammer',label:'Hammer',symbol:'🔨',drag:.08},{id:'feather',label:'Feather',symbol:'🪶',drag:4.5},{id:'ball',label:'Ball',symbol:'●',drag:.18},{id:'paper',label:'Paper',symbol:'▱',drag:2.6},{id:'rock',label:'Rock',symbol:'◆',drag:.1},{id:'bottle',label:'Bottle',symbol:'▯',drag:.5}];
export function dropDistance(time,world,air,id){const g=world==='mars'?3.71:9.81,k=air?(OBJECTS.find(o=>o.id===id)?.drag||.1)*(world==='mars'?.02:1):0;return Math.min(4,k?g/k*(time-(1-Math.exp(-k*time))/k):.5*g*time*time);}
export function plantApply(plants,stock,index,item){const needs=['water','lamp','nutrient'],targets=[2,1,1];if(index<0||index>2||needs[index]!==item)return{ok:false,why:'Check the sensor. This plant needs '+needs[index]+'.'};if(plants[index]>=targets[index])return{ok:false,why:'This plant has enough. Save supplies for its neighbors.'};if(!stock[item])return{ok:false,why:'That supply is empty. Reset the tray to try again.'};plants[index]++;stock[item]--;return{ok:true,done:plants.every((n,i)=>n===targets[i])};}
export function readProgress(storage){try{const d=JSON.parse(storage.getItem(SAVE)||'{}');return{done:LABS.filter(l=>Array.isArray(d.done)&&d.done.includes(l.id)).map(l=>l.id),motion:!!d.motion};}catch{return{done:[],motion:false};}}

export function makeYard(round=0){const flipX=round%2===1,flipY=Math.floor(round/2)%2===1,dx=round%3===2?20:0;const transform=p=>({...p,x:flipX?1040-p.x:p.x,y:flipY?550-p.y:p.y});const flags=[[3,6],[1,4],[1,6]][round%3];const nodes=NODES.map((p,i)=>transform({...p,x:p.x+(i===3?dx:0),flag:flags.includes(i)}));const obstacles=OBSTACLES.map(transform);return{nodes,obstacles,flags,title:['Sample run','Habitat delivery','Lost toolkit','New survey','Rock detour','Supply run'][round%6]};}
export function checkYard(yard,ids){if(ids[0]!==0||ids.some(i=>!yard.nodes[i]))return{ok:false,why:'Start at dot 1.',segments:[]};const segments=[];for(let i=1;i<ids.length;i++){const a=yard.nodes[ids[i-1]],b=yard.nodes[ids[i]],len=Math.hypot(b.x-a.x,b.y-a.y);let hit=1;for(const o of yard.obstacles){const dx=b.x-a.x,dy=b.y-a.y,px=a.x-o.x,py=a.y-o.y,A=dx*dx+dy*dy,B=2*(px*dx+py*dy),C=px*px+py*py-(o.r+14)**2,D=B*B-4*A*C;if(A&&D>=0){const t=(-B-Math.sqrt(D))/(2*A);if(t>=0&&t<hit)hit=t;}}segments.push({a,b,len,hit});if(hit<1)return{ok:false,why:'A rock is in the way. Pick another dot.',segments};}return{ok:ids.at(-1)===7&&yard.flags.every(i=>ids.includes(i)),why:ids.at(-1)!==7?'Finish at dot 8.':'Collect both flags first.',segments};}
export const NEEDS={water:{icon:'💧',label:'Water',hint:'Dry roots'},lamp:{icon:'☀',label:'Light',hint:'Too dark'},nutrient:{icon:'⚗',label:'Plant food',hint:'Low minerals'},fan:{icon:'❄',label:'Cooling fan',hint:'Too hot'},drain:{icon:'↧',label:'Drain tray',hint:'Soggy roots'}};
export function makeGarden(round=0){const species=['Lettuce','Tomato','Basil','Radish','Strawberry','Bean'],sets=[['water','lamp','nutrient'],['fan','water','drain'],['nutrient','lamp','water'],['drain','fan','nutrient'],['lamp','water','fan'],['water','drain','nutrient']],needs=sets[round%sets.length],stock={};const plants=needs.map((need,i)=>{const amount=need==='water'?1+round%2:1;stock[need]=(stock[need]||0)+amount;return{name:species[(round+i)%6],need,amount};});return{plants,stock};}
export function tendPlant(garden,counts,stock,index,item){const p=garden.plants[index];if(!p||p.need!==item)return{ok:false,why:p?`${p.name} needs ${NEEDS[p.need].label.toLowerCase()}.`:'Choose a plant.'};if(counts[index]>=p.amount)return{ok:false,why:'This plant is ready. Help another one.'};if(!stock[item])return{ok:false,why:'That tray is empty.'};counts[index]++;stock[item]--;return{ok:true,done:counts.every((n,i)=>n>=garden.plants[i].amount)};}
export function landingTime(world,air,id){let lo=0,hi=20;for(let i=0;i<50;i++){const mid=(lo+hi)/2;if(dropDistance(mid,world,air,id)>=4)hi=mid;else lo=mid;}return hi;}
export function gravityResult(world,air,pair){const a=landingTime(world,air,pair[0]),b=landingTime(world,air,pair[1]);return Math.abs(a-b)<.025?'together':a<b?'A':'B';}
export function gravityReason(world,air,pair){if(!air)return'No air pushes back, so gravity speeds both up equally.';const result=gravityResult(world,air,pair);if(result==='together')return world==='mars'?'Mars has very thin air. These land almost together in our model.':'Air affects these two by almost the same amount. They land almost together.';const slow=pair[result==='A'?1:0],name=OBJECTS.find(o=>o.id===slow).label.toLowerCase();const reason={feather:'its large surface catches lots of air for its tiny mass',paper:'its broad, light sheet catches air',bottle:'its hollow body catches more air for its mass',ball:'its size catches more air for its mass',rock:'its rough shape catches slightly more air for its mass',hammer:'its shape catches air'}[slow];return`The ${name} falls slower: ${reason}.`;}
export const AIR_ROUNDS=[{id:'oxygen',name:'Make breathing air',hint:'Add water. Plug in power.',inputs:['h2o','energy'],science:'Electricity splits water into hydrogen and oxygen. Oxygen goes to the crew; hydrogen stays separate.'},{id:'scrub',name:'Clean the cabin air',hint:'Fit the CO₂ filter. Start the fan.',inputs:['filter','fan'],science:'A sorbent captures carbon dioxide from cabin air. It does not turn CO₂ into oxygen.'},{id:'water',name:'Catch water from air',hint:'Fit the cold coil. Start the fan.',inputs:['coil','fan'],science:'Water vapor condenses on a cold surface. The collected water still needs treatment before it is drinkable.'}];
